const state={screen:'today',history:[],text:'',transcript:'',candidates:[]};
const content=document.getElementById('content');
const overlay=document.getElementById('overlay');
const backBtn=document.getElementById('backBtn');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const task=(title,meta='',done=false)=>`<li><div class="row"><span class="check ${done?'done':''}">${done?'✓':''}</span><div><b>${title}</b>${meta?`<div class="meta">${meta}</div>`:''}</div></div></li>`;
function push(screen){if(state.screen!==screen)state.history.push(state.screen);state.screen=screen;overlay.innerHTML='';render()}
function back(){const p=state.history.pop();state.screen=p||'today';overlay.innerHTML='';render()}
function active(){document.querySelectorAll('.navitem').forEach(b=>b.classList.toggle('active',b.dataset.screen===state.screen));backBtn.style.visibility=state.screen==='today'?'hidden':'visible'}
function today(){return `<div class="page-head"><div><div class="eyebrow">9月12日（土） · 今日の段取り</div><h1>今日</h1></div><button id="todayAdd">＋ 追加</button></div><div class="shortcut-row"><button class="shortcut primary-short" data-screen="checkin"><span>📝</span>入力</button><button class="shortcut" data-screen="requests"><span>🙏</span>お願い</button><button class="shortcut" data-screen="handovers"><span>💬</span>共有</button></div><section class="card concierge-card"><div class="row"><div class="bot">🤖</div><div><div class="eyebrow">書いても、話しても</div><h2>おうちコンシェルジュ</h2><div class="meta">予定・お願い・買い物などをまとめて入力</div></div><button data-screen="concierge">話す</button></div></section><section class="card"><div class="row between"><div><div class="eyebrow">今日をしめくくる</div><h2>🌙 今夜の入力</h2><div class="meta">残り3件。例外だけ詳しく入力できます。</div></div><button class="primary" data-screen="checkin">入力する</button></div></section><section class="card" style="border-color:#166b5d"><div class="row between"><div><div class="eyebrow">まず確認</div><h2>返事が必要です</h2></div><span class="badge pink">1件</span></div><div class="divider"></div><b>金曜のお迎えをお願い</b><div class="meta">ママから · 9/13まで</div><div class="request-actions"><button class="accept">やる</button><button class="decline">難しい</button><button class="secondary" data-screen="requests">その他の返答</button></div></section><div class="next-hero"><span class="pill">次にやること</span><div class="meta" style="color:#dfe9ff;margin-top:7px">19:00</div><h2>洗濯</h2><p>あなたの担当です。</p><button>開く →</button></div><section class="card"><div class="row between"><h2>今日の予定</h2><span class="badge">3件</span></div><ul class="list"><li><b>8:30 登園（はる）</b></li><li><b>15:00 スイミング（はる）</b></li><li><b>18:00 夕食</b></li></ul></section><section class="card compact"><div class="eyebrow">先の見通し</div><h2>明日の予定</h2><p>送 <span class="token p">P</span> ｜ 迎 <span class="token m">M</span></p><button class="textbtn" data-screen="week">週の予定を開く</button></section><section class="card"><div class="row between"><h2>朝準備 3/4完了</h2><span class="badge green">朝のまとめ</span></div><ul class="list">${task('水着を準備','未完了')}</ul></section><section class="card"><h2>夜の定例作業</h2><ul class="list">${task('洗濯','19:00')}${task('お風呂掃除','20:00')}</ul></section><section class="card compact"><div class="eyebrow">相手の重要な予定</div><h2>ここだけ確認</h2><p>金曜のお迎え対応</p></section><section class="card compact"><b>買い物（未購入4件） ▼</b></section>`}
function week(){const days=[['9/8 月','送 P ｜ 迎 M',['8:30 登園','18:00 夕食']],['9/9 火','送 P ｜ 迎 M',['15:00 スイミング']],['9/10 水','送 P ｜ 迎 M',['19:00 買い物']],['9/11 木','送 M ｜ 迎 M',['8:30 登園']],['9/12 金','送 P ｜ 迎 P',['9:30 小児科','15:00 スイミング']],['9/13 土','—',['10:00 公園']],['9/14 日','—',['予定なし']]];return `<div class="page-head"><div><div class="eyebrow">家族の見通し</div><h1>今週</h1></div><button data-screen="requests">お願いする</button></div><div class="calendar-toolbar"><button class="secondary">前週</button><b>9/8〜9/14</b><button class="secondary">次週</button></div><div class="week-cards">${days.map(d=>`<section class="day-card"><div class="row between"><h2>${d[0]}</h2><b>${d[1]}</b></div><ul class="list">${d[2].map(x=>`<li><button class="textbtn agendaBtn">${x}</button></li>`).join('')}</ul><button class="textbtn" data-screen="requests">別のお願いをする</button></section>`).join('')}</div>`}
function month(){let c='';for(let i=1;i<=30;i++){const e=i===12?['0830 登園','1500 スイミング']:i===13?['1000 公園']:i===20?['運動会']:[];c+=`<button class="day ${i===12?'today':''}" data-date="9/${i}"><b>${i}</b>${e.map(x=>`<span class="eventline">${x}</span>`).join('')}</button>`}return `<div class="calendar-toolbar"><button class="secondary">‹</button><div style="text-align:center"><div class="eyebrow">全体を把握</div><h1 style="font-size:24px">2026年9月</h1></div><button class="secondary">›</button></div><div class="calendar-grid">${['月','火','水','木','金','土','日'].map(x=>`<div class="dow">${x}</div>`).join('')}<div></div>${c}</div><p class="meta">日付をタップすると、その日の予定・送迎・やることをまとめて確認できます。</p>`}
function requests(){return `<div class="page-head"><h1>お願い</h1><button>＋ お願いを送る</button></div><div class="tabs"><button class="active">受け取ったお願い</button><button>送ったお願い</button></div><section class="card"><b>金曜のお迎えをお願い</b><div class="meta">作業期限: 9/13 18:00 · ママから</div><p>金曜だけお願いできますか？</p><div class="request-actions"><button class="accept">やる</button><button class="decline">難しい</button><button class="secondary" id="otherReply">その他の返答</button></div><div id="otherArea"></div></section><section class="card"><b>ゴミ出しをお願い</b><div class="meta">作業期限: 9/14 07:30</div><span class="badge">保留中</span></section>`}
function shopping(){return `<div class="page-head"><h1>買い物</h1><button>＋ 追加</button></div><div class="tabs"><button class="active">欲しい</button><button>担当決定</button><button>注文済み</button></div><section class="card"><h2>欲しい (4)</h2><ul class="list"><li><b>牛乳</b><div class="meta">店舗 · 未担当</div><button class="primary">自分がやる</button></li><li><b>卵</b><div class="meta">どちらでも · 誰でもOK</div></li><li><b>子どもの歯ブラシ</b><div class="meta">オンライン · ママ担当</div><button class="primary">注文した</button></li><li><b>食パン</b><div class="meta">店舗 · 未担当</div></li></ul></section>`}
function handovers(){return `<div class="page-head"><h1>引き継ぎ</h1><button>＋ 引き継ぎを書く</button></div><section class="card" style="background:var(--unread)"><div class="meta">9/12 · 朝 · tomorrow_preparation</div><p><b>はるの水着準備</b></p><button class="primary">既読にする</button></section><section class="card"><div class="meta">9/11 · 夜</div><p><b>園の書類提出は9/16まで</b></p><span class="badge orange">重要</span></section>`}
function history(){return `<div class="page-head"><h1>履歴</h1></div><p class="meta">直近2週間の予定と実際の結果です。</p><div class="tabs"><button class="active">すべて</button><button>定例作業</button><button>予定</button><button>お願い</button></div><section class="card"><div class="row between"><b>洗濯</b><span class="badge green">完了（期限内）</span></div><div class="meta">予定: 9/12 19:00 パパ</div><div class="meta">実績: 9/12 19:26 パパ</div><button class="textbtn">実績を訂正</button></section><section class="card"><div class="row between"><b>金曜のお迎え</b><span class="badge">進行中</span></div><div class="meta">担当変更: パパ → ママ</div></section>`}
function event(){return `<div class="page-head"><h1 style="font-size:24px">イベント・予定を追加</h1></div><div class="tabs"><button class="active">手入力</button><button>AIで入力</button></div><div class="field"><label>タイトル</label><input value="運動会"></div><div class="field"><label>日時</label><input value="2026/9/20 8:30"></div><div class="field"><label>場所</label><input value="小学校 校庭"></div><div class="field"><label>メモ</label><textarea>体操服・水筒・お弁当</textarea></div><div class="notice">AI支援: 自然文から予定と準備ToDo候補を作れます。</div><button class="primary">保存</button>`}
function checkin(){return `<div class="page-head"><div><div class="eyebrow">🌙 今夜の入力</div><h1 style="font-size:24px">今日はどうでしたか？</h1></div></div><p class="muted">細かな入力は例外があるときだけで大丈夫です。</p><div class="request-actions"><button class="accept">全部やった</button><button class="secondary">大体やった</button><button class="secondary" id="individualBtn">個別で答える</button></div><div id="individualArea"></div>`}
function settings(){const rows=[['🔁','いつもの担当','送り・お迎え、夜の家事、朝の準備'],['🎨','カテゴリ','予定追加で選ぶ項目と色'],['💬','家庭内用語','LINE・コンシェルジュで使う言い回しと意味'],['🔔','通知','LINEとアプリ内のお知らせ'],['📨','引き継ぎ','朝・夜の共有メモ'],['🧪','1人テストモード','安全な確認用'],['📅','Googleカレンダー','連携設定'],['👨‍👩‍👧','家族','P/M表示と担当色']];return `<div class="page-head"><h1>設定</h1></div><p class="muted">いつもの担当や通知を、家族のルールとして整えます。</p><section class="card" style="padding:0">${rows.map(x=>`<div class="settings-link"><div class="sicon">${x[0]}</div><div><b>${x[1]}</b><small>${x[2]}</small></div><span style="margin-left:auto">›</span></div>`).join('')}</section>`}
function nursery(){return `<div class="page-head"><div><div class="eyebrow">園のおたより</div><h1 style="font-size:24px">確認して登録</h1></div><span class="badge orange">レビュー待ち</span></div><div class="notice">はる・○○園・ひまわり組 と推定しました。明記内容とAI推測を分けて表示します。</div><section class="card"><div class="row between"><div><div class="eyebrow">おたよりに明記 · 確度 高</div><h2>準備するもの</h2></div><input type="checkbox" checked></div><p class="meta">出典: 画像1ページ目 · 持ち物欄</p><span class="badge green">登録おすすめ</span><div class="field"><label>内容</label><input value="水着・タオル"></div></section><section class="card"><div class="row between"><div><div class="eyebrow">AIの推測 · 確度 中</div><h2>ToDo</h2></div><input type="checkbox" checked></div><p class="meta">出典: 画像1ページ目</p><div class="field"><label>内容</label><input value="前日に水着を準備"></div></section><section class="card"><div class="eyebrow">おたよりに明記</div><h2>その他の予定</h2><p>写真販売 9/20〜</p><span class="badge">その他の予定 — 消さずに確認</span></section><button class="primary" style="width:100%">選択した内容を登録</button><button class="secondary" style="width:100%;margin-top:8px">元画像を見る</button>`}
function concierge(){return `<div class="concierge-hero"><div class="botbig">🤖</div><h1 style="font-size:24px">おうちコンシェルジュ</h1><p class="muted">予定・やること・買い物・お願い・実績など<br>家のこと、なんでも話しかけてください。</p></div><section class="card"><div class="eyebrow">例えば…</div><div class="chips"><button class="chip sample">明日は水遊び。水着準備しといて</button><button class="chip sample">牛乳なくなりそう。買い物に追加</button><button class="chip sample">金曜のお迎え、ママにお願い</button></div></section><div class="composebox"><textarea id="conciergeInput" placeholder="何でも話しかけてください…">${esc(state.text)}</textarea><button class="mic" id="micBtn">🎙</button><button class="send" id="interpretBtn">➤</button></div><p class="meta">音声は話し終わってから文字起こし。軽い誤字・言い直しはAIが文脈で補います。</p>`}
function record(){return `<div class="recording"><div class="eyebrow">おうちコンシェルジュ</div><h1 style="font-size:24px">録音中…</h1><p class="muted">話し終わったら停止してください</p><div class="pulse">🎙</div><div class="timer" id="timer">0:18</div><button class="secondary" id="stopRec">停止</button></div>`}
function transcript(){return `<div class="page-head"><h1 style="font-size:22px">文字起こしを確認</h1></div><div class="notice">✓ 文字起こしが完了しました</div><div class="field"><textarea id="transcriptArea">${esc(state.transcript)}</textarea></div><button class="primary" id="interpretTranscript" style="width:100%">この内容でAIに解釈してもらう</button><button class="secondary" data-screen="record" style="width:100%;margin-top:8px">もう一度録音する</button>`}
const icons={共有:'💬',ToDo:'✅',買い物:'🛒',お願い:'🙏',予定:'📅',実績:'🧾'};
function results(){return `<div class="page-head"><div><div class="eyebrow">AIが整理した候補</div><h1 style="font-size:22px">こんな内容だと思います</h1></div></div><div class="notice">確認して追加してください。曖昧な項目だけ編集できます。</div>${state.candidates.map((c,i)=>`<section class="candidate"><div class="candidate-head"><div class="ctype">${icons[c.type]||'✨'}</div><div><span class="badge ${c.type==='お願い'?'pink':c.type==='買い物'?'orange':c.type==='ToDo'?'green':''}">${c.type}</span><h3>${esc(c.title)}</h3></div><button class="edit" data-edit="${i}">編集</button><input type="checkbox" data-check="${i}" ${c.selected?'checked':''}></div>${c.date?`<div class="meta">${esc(c.date)}</div>`:''}${c.note?`<p class="meta">${esc(c.note)}</p>`:''}</section>`).join('')}<button class="primary" id="registerBtn" style="width:100%">選択した内容を登録する</button><button class="secondary" id="backToConcierge" style="width:100%;margin-top:8px">内容を修正する</button>`}
function success(){return `<div class="success"><div class="successmark">🎉</div><h1 style="font-size:25px">登録が完了しました！</h1><p>${state.candidates.filter(x=>x.selected).length}件を登録しました。</p><button class="primary" data-screen="concierge">続けて入力する</button><button class="secondary" data-screen="today">今日へ戻る</button></div>`}
const screens={today,week,month,requests,shopping,handovers,history,event,checkin,settings,nursery,concierge,record,transcript,results,success};
function candidates(text){const cs=[];for(const p of text.split(/[。！!\n]+/).map(x=>x.trim()).filter(Boolean)){if(/なくな|買|牛乳|卵/.test(p))cs.push({type:'買い物',title:(p.match(/牛乳|卵|歯ブラシ|食パン/)||[p])[0],selected:true});else if(/お願い|ママに|パパに/.test(p))cs.push({type:'お願い',title:p.replace(/ママに|パパに|お願い.*$/g,'').trim()||p,date:/金曜/.test(p)?'9/13（金）':'',note:'担当は確定前に確認します',selected:true});else if(/やった|終わった|かけた/.test(p))cs.push({type:'実績',title:p.replace(/やった|終わった/g,'').trim()||p,selected:true});else if(/準備|しとく|水着/.test(p))cs.push({type:'ToDo',title:p.replace(/しといて|しとく/g,'').trim(),selected:true});else cs.push({type:'共有',title:p,date:/明日/.test(p)?'9/13（土）':'',selected:true})}return cs.slice(0,8)}
function quickAdd(){overlay.innerHTML=`<div class="modalback"><div class="modal"><div class="modal-head"><h2>追加するもの</h2><button class="close" id="closeModal">×</button></div><button class="quick-option conc" data-screen="concierge"><span class="qicon">🤖</span><span><b>おうちコンシェルジュ</b><small>話しても、書いても。まとめておまかせ。</small></span></button>${[['✅','単発ToDoを追加','今日やること・特別な持ち物','event'],['📅','イベント・予定を追加','行事と準備ToDoをまとめて確認','event'],['🙏','お願いを送る','担当変更や依頼','requests'],['🛒','買い物を追加','','shopping'],['💬','引き継ぎを書く','','handovers'],['🔁','定例を追加','送迎・朝夜家事の毎週ルール','settings'],['🌅','朝準備を編集','','settings']].map(x=>`<button class="quick-option" data-screen="${x[3]}"><span class="qicon">${x[0]}</span><span><b>${x[1]}</b>${x[2]?`<small>${x[2]}</small>`:''}</span></button>`).join('')}</div></div>`;bindOverlay()}
function agenda(date){overlay.innerHTML=`<div class="sheet"><div class="modal-head"><div><div class="eyebrow">${date}</div><h2>予定・送迎・やること</h2></div><button class="close" id="closeSheet">×</button></div><section class="card compact"><b>送 <span class="token p">P</span> ｜ 迎 <span class="token m">M</span></b></section><section class="card compact"><b>8:30 登園（はる）</b></section><section class="card compact"><b>15:00 スイミング（はる）</b></section><button class="primary" data-screen="event" style="width:100%">この日に追加</button></div>`;document.getElementById('closeSheet').onclick=()=>overlay.innerHTML='';overlay.querySelector('[data-screen]').onclick=()=>push('event')}
function edit(i){const c=state.candidates[i];overlay.innerHTML=`<div class="modalback"><div class="modal"><div class="modal-head"><h2>候補を編集</h2><button class="close" id="closeModal">×</button></div><div class="field"><label>種類</label><select id="eType">${['共有','ToDo','買い物','お願い','予定','実績'].map(x=>`<option ${x===c.type?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>タイトル</label><input id="eTitle" value="${esc(c.title)}"></div><button class="primary" id="saveEdit">保存</button></div></div>`;document.getElementById('closeModal').onclick=()=>overlay.innerHTML='';document.getElementById('saveEdit').onclick=()=>{c.type=document.getElementById('eType').value;c.title=document.getElementById('eTitle').value;overlay.innerHTML='';render()}}
function bindOverlay(){document.getElementById('closeModal').onclick=()=>overlay.innerHTML='';overlay.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>push(b.dataset.screen))}
function bind(){document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>push(b.dataset.screen));document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>agenda(b.dataset.date));document.querySelectorAll('.agendaBtn').forEach(b=>b.onclick=()=>agenda('9/12（金）'));const ta=document.getElementById('conciergeInput');if(ta)ta.oninput=e=>state.text=e.target.value;document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>{state.text=b.textContent;render()});const mic=document.getElementById('micBtn');if(mic)mic.onclick=()=>push('record');const stop=document.getElementById('stopRec');if(stop)stop.onclick=()=>{state.transcript='明日は水遊びだから水着準備しといて。牛乳なくなりそう。金曜のお迎えママにお願い。';push('transcript')};const send=document.getElementById('interpretBtn');if(send)send.onclick=()=>{state.transcript=state.text||'明日は水遊び。水着準備しといて。牛乳なくなりそう。金曜のお迎えママにお願い。';state.candidates=candidates(state.transcript);push('results')};const tr=document.getElementById('interpretTranscript');if(tr)tr.onclick=()=>{state.transcript=document.getElementById('transcriptArea').value;state.candidates=candidates(state.transcript);push('results')};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(+b.dataset.edit));document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>state.candidates[+b.dataset.check].selected=b.checked);const reg=document.getElementById('registerBtn');if(reg)reg.onclick=()=>push('success');const rev=document.getElementById('backToConcierge');if(rev)rev.onclick=()=>{state.text=state.transcript;push('concierge')};const other=document.getElementById('otherReply');if(other)other.onclick=()=>document.getElementById('otherArea').innerHTML='<div class="request-actions"><button class="secondary">確認してみる</button><button class="secondary">相談する</button></div><p class="meta">担当はこの時点では変わりません。</p>';const indiv=document.getElementById('individualBtn');if(indiv)indiv.onclick=()=>document.getElementById('individualArea').innerHTML=`<section class="card"><h2>個別入力</h2><ul class="list">${task('洗濯','完了')}${task('お風呂掃除','未完了')}${task('明日の水着準備','未完了')}</ul></section>`;const add=document.getElementById('todayAdd');if(add)add.onclick=quickAdd}
function render(){active();content.innerHTML=(screens[state.screen]||today)();bind();content.scrollTop=0}
document.querySelectorAll('.devbar [data-screen],.bottom-nav [data-screen]').forEach(b=>b.onclick=()=>push(b.dataset.screen));document.getElementById('addBtn').onclick=quickAdd;document.getElementById('settingsBtn').onclick=()=>push('settings');backBtn.onclick=back;render();
